CustomField.formula:
IF(
/*If Account is Country Parent, stores DM_Cloud_Sales_Rep__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), DM_Cloud_Sales_Rep__c ,
IF(
/*If Account is Sales site, stores Country Parent Account's DM_Cloud_Sales_Rep__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.DM_Cloud_Sales_Rep__c,DM_Cloud_Sales_Rep__c))
